fn native_routing_candidates(&self, primary: &NativeModelConfig) -> Vec<NativeModelConfig> {
    match primary {
        NativeModelConfig::Managed(_) => self.managed_local.routing_candidates(),
        NativeModelConfig::Local(primary) => {
            let endpoint = primary.endpoint.trim().trim_end_matches('/');
            self.installed_model_inventory
                .as_ref()
                .filter(|inventory| {
                    inventory.endpoint.trim().trim_end_matches('/') == endpoint
                })
                .map(|inventory| {
                    inventory
                        .models
                        .iter()
                        .filter(|model| model.name.trim() != primary.model.trim())
                        .map(|model| {
                            NativeModelConfig::Local(LocalModelConfig {
                                endpoint: primary.endpoint.clone(),
                                model: model.name.clone(),
                            })
                        })
                        .collect()
                })
                .unwrap_or_default()
        }
        NativeModelConfig::Hosted(_) => Vec::new(),
    }
}
